const ee = require('@google/earthengine'); 
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const palmSprings = ee.Geometry.Point([-116.5453, 33.7853]); // Palm Springs, CA

  // MODIS MOD11A2 provides 8-day composites.
  // July 15-21 falls into the 8-day composite that typically starts around July 17 (Day of Year 198 or 193 depending on year/product internal calendar).
  // We'll filter for the composite that starts on or just before July 17 (DOY 193-200 or 198-205).
  // A robust way is to define the target DOY range and select the composite whose start is within or closest to it.
  // For MOD11A2, day 193 covers July 12-19, and day 201 covers July 20-27.
  // The period July 15-21 is largely covered by the 8-day period starting around Day of Year (DOY) 193 or 194.
  // Let's target the composite that starts on DOY 193 (July 12-19) or DOY 194.
  // We will pick the 8-day composite that spans the target period as best as possible.
  // MODIS 8-day products have specific start dates. For 2017, the 8-day composite starting July 17 (DOY 198) covers July 17-24.
  // Let's filter for the composite covering July 15-21, 2017. The closest MOD11A2 composite typically starts around July 17.
  // We'll use a date filter to capture the 8-day composite that contains the target week.

  const targetDate2017 = '2017-07-17'; // A central date for the target week
  const targetDateRangeStart = '07-15';
  const targetDateRangeEnd = '07-21';

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/061/MOD11A2');

  // Function to get LST for a specific year and period
  const getLST = (year, targetMonthDayStart, targetMonthDayEnd, geometry) => {
    const yearStart = `${year}-${targetMonthDayStart}`;
    const yearEnd = `${year}-${targetMonthDayEnd}`;

    let filteredCollection = collection
      .filterDate(yearStart, yearEnd)
      .filterBounds(geometry);

    // If no images found for the specific target date range, try a broader search for the relevant 8-day composite.
    if (filteredCollection.size().getInfo() === 0) {
      // Find the 8-day composite that contains the target week.
      // MOD11A2 typically has composites starting around day 1, 9, 17, 25 of the month.
      // For July 15-21, the composite starting ~July 17 (DOY 198) is most relevant.
      // Let's search for an image within a wider window around July 17.
      const broaderStart = ee.Date.fromYMD(year, 7, 10); // July 10
      const broaderEnd = ee.Date.fromYMD(year, 7, 25);   // July 25
      filteredCollection = collection
        .filterDate(broaderStart, broaderEnd)
        .filterBounds(geometry)
        .sort('system:time_start'); // Sort to pick the closest or first relevant composite.

      // If still empty, return an empty collection
      if (filteredCollection.size().getInfo() === 0) {
          return ee.ImageCollection([]);
      }
    }

    // Usually, there will be one 8-day composite relevant for the period.
    // If multiple are found (e.g., due to broader search), take the first one or the one closest to mid-July.
    const image = ee.Image(filteredCollection.first());

    if (!image) { // Check if 'first()' returned null (empty collection after filter)
        return ee.ImageCollection([]); // Return an empty collection equivalent for consistency
    }

    // Select LST_Day_1km band and apply scale factor
    const lst = image.select('LST_Day_1km').multiply(0.02); // Scale factor for LST

    // Apply quality mask from QC_Day band
    // Bit 0-1: LST quality (00 = good quality)
    // Bit 2-3: Emissivity error (00 = < 0.01)
    // Bit 4-5: LST error (00 = < 1K)
    // Bit 6-7: Cloud effects (00 = clear sky)
    const qc = image.select('QC_Day');
    const goodQuality = qc.bitwiseAnd(3).eq(0); // LST quality (bits 0-1) is '00' (Good Quality)
    const clearSky = qc.rightShift(6).bitwiseAnd(3).eq(0); // Cloud effects (bits 6-7) is '00' (Clear sky)

    // Combine masks
    const validPixelsMask = goodQuality.and(clearSky);

    // Apply the mask to LST
    const maskedLST = lst.updateMask(validPixelsMask);

    return maskedLST;
  };

  // LST for 2017
  const lst2017Image = getLST(2017, targetDateRangeStart, targetDateRangeEnd, palmSprings);

  if (lst2017Image instanceof ee.ImageCollection && lst2017Image.size().getInfo() === 0) {
      console.log("No images found for 2017 in the specified date/location.");
      console.log("C1");
      return;
  }

  // Calculate pixel count for 2017
  const scale = 1000; // MODIS resolution is 1km
  let count2017 = await lst2017Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: palmSprings.buffer(5000), // Buffer for a more representative area
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  if (count2017 === null) count2017 = 0; // Handle case where getInfo() returns null for no pixels

  if (count2017 === 0) {
    console.log("2017 Images found, but 0 valid pixels after masking.");
    console.log("C2");
    return;
  }

  const meanLST2017 = await lst2017Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: palmSprings.buffer(5000),
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  if (meanLST2017 === null || isNaN(meanLST2017)) {
    console.log("2017 LST calculation failed.");
    console.log("C3");
    return;
  }

  // LST for 2001-2010 average
  let sumLSTAverage = 0;
  let yearCount = 0;
  let totalValidPixelsAverage = 0;

  for (let year = 2001; year <= 2010; year++) {
    const lstImageYear = getLST(year, targetDateRangeStart, targetDateRangeEnd, palmSprings);

    if (lstImageYear instanceof ee.ImageCollection && lstImageYear.size().getInfo() === 0) {
        // Skip years with no data, but continue to build the average from available years
        console.log(`No images found for year ${year}. Skipping year for average.`);
        continue; 
    }

    const yearMean = await lstImageYear.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: palmSprings.buffer(5000),
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    const yearCountPixels = await lstImageYear.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: palmSprings.buffer(5000),
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (yearMean !== null && !isNaN(yearMean) && yearCountPixels > 0) {
      sumLSTAverage += yearMean;
      yearCount++;
      totalValidPixelsAverage += yearCountPixels;
    } else {
      console.log(`Warning: LST for ${year} is invalid or has 0 pixels. Skipping.`);
    }
  }

  if (yearCount === 0) {
    console.log("No valid data for 2001-2010 average after filtering and masking.");
    console.log("C1"); // Or C2 depending on if images existed but were masked
    return;
  }

  const meanLSTAverage = sumLSTAverage / yearCount;

  // 5. Validation & Final Answer
  console.log(`2017 LST (C): ${meanLST2017.toFixed(2)}, Pixels: ${count2017}`);
  console.log(`2001-2010 Avg LST (C): ${meanLSTAverage.toFixed(2)}, Years: ${yearCount}, Total Pixels: ${totalValidPixelsAverage}`);

  if (meanLST2017 === null || isNaN(meanLST2017) || meanLSTAverage === null || isNaN(meanLSTAverage)) {
    console.log("Calculation failure for one or both LST values.");
    console.log("C3");
  } else if (meanLST2017 > meanLSTAverage) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
